using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp.Admin { public partial class ProductsPage : WamoApp.AdminPage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetList() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Products", "View"); return AdminDataService.GetList("Products"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetDefinition() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Products", "View"); return AdminDataService.GetDefinitionMetadata("Products"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object DeleteRecord(string id) { SecurityHelper.ValidateCsrfOrThrow(); SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Products", "Delete"); return AdminDataService.Delete("Products", id); } } }
